[   SuppressBPWarning('BPParameterNotUsed', 'False positive'),
    FormDataFieldEventHandler(formDataFieldStr(EntAssetWorkOrderJournal, ProjJournalTransHour, Resource), FormDataFieldEventType::Modified)]
public static void Resource_OnModified(FormDataObject sender, FormDataFieldEventArgs e)
{
    FormDataSource  ProjJournalTransHour_ds = sender.datasource();
    ProjJournalTrans projJournalTransHour = ProjJournalTransHour_ds.cursor();
    projJournalTransHour.avaSetCategoryFromResource();
}

